entries[424759] = { ["name"] = "Berserk", ["text"] = "Gain the Berserk ability:\n\nWhen activated, this ability causes your Mangle (Bear) and Lacerate abilities to hit up to 3 targets, Lacerate to cost no Rage, Mangle (Bear) to have no cooldown, and reduces the energy cost of all your Cat Form abilities by 50%. Lasts 15 sec. Requires Bear Form, Cat Form, or Dire Bear Form to activate.\n\nClears the effect of Fear and makes you immune to Fear for the duration." }
entries[424760] = { ["name"] = "Engrave Belt - Berserk", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Berserk rune:\n\nWhen activated, this ability causes your Mangle (Bear) and Lacerate abilities to hit up to 3 targets, Lacerate to cost no Rage, Mangle (Bear) to have no cooldown, and reduces the energy cost of all your Cat Form abilities by 50%. Lasts 15 sec. Requires Bear Form, Cat Form, or Dire Bear Form to activate.\n\nClears the effect of Fear and makes you immune to Fear for the duration." }
entries[424762] = { ["name"] = "King of the Jungle", ["text"] = "Gain the King of the Jungle ability:\n\nTiger's Fury now increases all physical damage you deal by 15% instead of by a flat value, and instantly grants you 60 Energy. It is no longer on the global cooldown, but it now has its own 30 sec cooldown. Additionally, Tiger's Fury will persist while not in Cat Form, but will cancel upon entering Bear Form or Dire Bear Form." }
entries[424765] = { ["name"] = "Engrave Boots - King of the Jungle", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the King of the Jungle rune:\n\nTiger's Fury now increases all physical damage you deal by 15% instead of by a flat value, and instantly grants you 60 Energy. It is no longer on the global cooldown, but it now has its own 30 sec cooldown. Additionally, Tiger's Fury will persist while not in Cat Form, but will cancel upon entering Bear Form or Dire Bear Form." }
entries[424785] = { ["name"] = "Saber Slash", ["text"] = "45 Energy Melee Range\nInstant\nRequires Melee Weapon\nViciously slash an enemy for 100% weapon damage, and cause the target to bleed for (Attack Power * 5 / 100) damage every 2 sec for 12 sec, stacking up to 3 times. Each stack also increases damage done by your Saber Slash and Sinister Strike by 50%. Awards 1 combo point.\n\nSaber Slash benefits from all talents and effects that trigger from or modify Sinister Strike." }
entries[424788] = { ["name"] = "Salvage", ["text"] = "Melee Range\n1 sec cast\nSalvage the wreckage of a shredder for spare parts." }
entries[424799] = { ["name"] = "Shiv", ["text"] = "20 Energy Melee Range\nInstant\nRequires Melee Weapon\nInstantly attack with your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards 1 combo point.\n\nShiv benefits from all talents and effects that trigger from or modify Sinister Strike." }
entries[424800] = { ["name"] = "Shiv", ["text"] = "Melee Range\nInstant\nRequires Melee Weapon\nInstantly attack with your off-hand weapon with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards 1 combo point." }
entries[424919] = { ["name"] = "Main Gauche", ["text"] = "15 Energy Melee Range\nInstant 15 sec cooldown\nRequires Melee Weapon\nInstantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by 100% for 5 sec or until you successfully parry. For 20 sec after using Main Gauche, Sinister Strike costs 20 less Energy, deals 50% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal 50% more damage. Awards 1 combo point.\n\nMain Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche." }
entries[424925] = { ["name"] = "Slaughter from the Shadows", ["text"] = "Reduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 70%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]" }
